url = "www.company-todo-list.com/bob"
webpage_content = get_webpage(url)
class TodoItem(BaseModel):
    task: str
    done: bool
todo_items = query_ai_assistant(f"Extract TODO items from webpage content: {webpage_content}", TodoItem)
if isinstance(todo_items, list):
    for item in todo_items:
        if not item.done:
            print(f"Doing task: {item.task}")
else:
    if not todo_items.done:
        print(f"Doing task: {todo_items.task}")
